// Connects Western catalog garments (see src/data/garments.js) to their
// pre-generated AI try-on results, the same idea as src/data/tryOnResults.js
// for Eastern wear — except Western is a top+bottom PAIR, so results are
// generated by your teammate is a shirt/polo tried on a model, that photo
// then combined with each of the 11 pants. There are two lookup shapes:
//
//   1. COMBO results — a specific top + a specific bottom together.
//      getWesternComboResult(topId, bottomId)
//
//   2. SINGLE results — just the top on its own (no bottom picked yet, or
//      the person is only trying the top). getWesternSingleResult(topId)
//
// Files live under public/results/western/:
//   shirt-pant/{shirtId}__{pantsId}.jpg   e.g. shirt-01__pants-01.jpg
//   polo-pant/{poloId}__{pantsId}.jpg     e.g. polo-03__pants-01.jpg
//   shirt-single/{shirtId}.png
//   polo-single/{poloId}.png
//
// ============================================================================
// HOW THE MATCHING WAS DONE — please read before trusting this blindly
// ============================================================================
// PANTS: certain match. The result files were literally named "pant (1)"
// through "pant (11)", and the catalog has exactly 11 pants (pants-01..11)
// in the same order — pant (N) -> pants-{N}.
//
// SHIRTS: high-confidence match. Result files were named "shirt (1)",
// "shirt (3)", "shirt (4)", "shirt (6)", "shirt (7)", "shirt (8)",
// "shirt (9)" — matched to shirt-01/03/04/06/07/08/09 by the same numbering
// convention as pants. Only 7 of the 10 catalog shirts have combo results;
// shirt-02, shirt-05, shirt-10 have none yet (not tried on by your
// teammate). Shirt SINGLE (no-pants) results additionally cover shirt-02 —
// so 8 of 10 shirts have at least a single result.
//
// POLOS: *** CONFIRMED ***. Originally matched by automated color-sampling
// (a guess), but the source photos your teammate used for the AI pipeline
// turned out to be recoverable ("polo (1).png", "polo (6).png",
// "polo (8).png", "polo (10).png", and one named "Screenshot ...png") —
// which map directly to catalog items by number, the same way shirts do.
// The "Screenshot" one wasn't a catalog item at all — it was a new black
// polo (with a chest pocket) that didn't exist in the catalog, so it's
// been added as polo-11. Corrected mapping:
//   "b"             -> polo-11 (Black Polo — NEW, added for this)
//   "download (2)"  -> polo-08 (Maroon Polo)
//   "download (2)h" -> polo-06 (Tan Polo)
//   "download (3)"  -> polo-10 (Navy Blue Polo)
//   "download (4)"  -> polo-01 (White Polo)
// (The original guess had "b"/"download(3)"/"download(4)" wrong — verified
// via a second color pass matched against the recovered source filenames.)
// Only 6 of the 11 catalog polos have results at all (polo-02, polo-04,
// polo-05, polo-07, polo-09 have none).
//
// SWEATSHIRTS: there was no "Sweatshirts" category in the catalog at all
// before this, so one was added (sweatshirt-01..05). Real flat product
// photos are now in place too, color-matched to these results by hue
// (Heather Grey, Cream, Blush Pink, Sky Blue, Camel — search garments.js
// for "sweatshirt-0"). Unlike polos, there was no ambiguity in which
// result belongs to which garment — each of the 5 sweatshirts had its own
// single-garment photo to match its combos against.

const SHIRT_PANT_COMBOS = {
  "shirt-01": range11("shirt-01"),
  "shirt-03": range11("shirt-03"),
  "shirt-04": range11("shirt-04"),
  "shirt-06": range11("shirt-06"),
  "shirt-07": range11("shirt-07"),
  "shirt-08": range11("shirt-08"),
  "shirt-09": range11("shirt-09"),
};

// polo-01 (was "download (4)") is missing pants-08/09/10 — those 3 combos
// don't exist, so getWesternComboResult falls back to the single result.
const POLO_PANT_COMBOS = {
  "polo-10": range11("polo-10", "polo-pant"),
  "polo-11": range11("polo-11", "polo-pant"),
  "polo-08": range11("polo-08", "polo-pant"),
  "polo-06": range11("polo-06", "polo-pant"),
  "polo-01": range11("polo-01", "polo-pant", [8, 9, 10]),
};

function range11(id, folder = "shirt-pant", skip = []) {
  const out = {};
  for (let n = 1; n <= 11; n++) {
    if (skip.includes(n)) continue;
    const pantsId = `pants-${String(n).padStart(2, "0")}`;
    out[pantsId] = `/results/western/${folder}/${id}__${pantsId}.jpg`;
  }
  return out;
}

const SHIRT_SINGLE_RESULTS = {
  "shirt-01": "/results/western/shirt-single/shirt-01.png",
  "shirt-02": "/results/western/shirt-single/shirt-02.png",
  "shirt-03": "/results/western/shirt-single/shirt-03.png",
  "shirt-04": "/results/western/shirt-single/shirt-04.png",
  "shirt-06": "/results/western/shirt-single/shirt-06.png",
  "shirt-07": "/results/western/shirt-single/shirt-07.png",
  "shirt-08": "/results/western/shirt-single/shirt-08.png",
  "shirt-09": "/results/western/shirt-single/shirt-09.png",
};

const POLO_SINGLE_RESULTS = {
  "polo-10": "/results/western/polo-single/polo-10.png",
  "polo-11": "/results/western/polo-single/polo-11.png",
  "polo-08": "/results/western/polo-single/polo-08.png",
  "polo-06": "/results/western/polo-single/polo-06.png",
  "polo-01": "/results/western/polo-single/polo-01.png",
};

// SWEATSHIRTS: 5 distinct sweatshirts, each with the full 11-pant combo
// set (no ambiguity here — each had its own single-garment result photo
// to match against, unlike the polos).
const SWEATSHIRT_PANT_COMBOS = {
  "sweatshirt-01": range11("sweatshirt-01", "sweatshirt-pant"),
  "sweatshirt-02": range11("sweatshirt-02", "sweatshirt-pant"),
  "sweatshirt-03": range11("sweatshirt-03", "sweatshirt-pant"),
  "sweatshirt-04": range11("sweatshirt-04", "sweatshirt-pant"),
  "sweatshirt-05": range11("sweatshirt-05", "sweatshirt-pant"),
};

const SWEATSHIRT_SINGLE_RESULTS = {
  "sweatshirt-01": "/results/western/sweatshirt-single/sweatshirt-01.png",
  "sweatshirt-02": "/results/western/sweatshirt-single/sweatshirt-02.png",
  "sweatshirt-03": "/results/western/sweatshirt-single/sweatshirt-03.png",
  "sweatshirt-04": "/results/western/sweatshirt-single/sweatshirt-04.png",
  "sweatshirt-05": "/results/western/sweatshirt-single/sweatshirt-05.png",
};

// Pants tried on alone (no top) — numbered exactly like the pants catalog
// (pant (N) -> pants-{N}), so this is a certain match, same as the pants
// side of the shirt/polo/sweatshirt combos. NOTE: "pants-01" has no
// catalog entry right now (it was commented out — see garments.js, the
// "Red Pant" removal). This result is still wired up so it's ready the
// moment pants-01 comes back; until then it's simply unreachable since
// there's no catalog id to select it with.
const PANTS_SINGLE_RESULTS = {
  "pants-01": "/results/western/pants-single/pants-01.jpg",
  "pants-02": "/results/western/pants-single/pants-02.jpg",
  "pants-03": "/results/western/pants-single/pants-03.jpg",
  "pants-04": "/results/western/pants-single/pants-04.jpg",
  "pants-05": "/results/western/pants-single/pants-05.jpg",
  "pants-06": "/results/western/pants-single/pants-06.jpg",
  "pants-07": "/results/western/pants-single/pants-07.jpg",
  "pants-08": "/results/western/pants-single/pants-08.jpg",
  "pants-09": "/results/western/pants-single/pants-09.jpg",
  "pants-10": "/results/western/pants-single/pants-10.jpg",
  "pants-11": "/results/western/pants-single/pants-11.jpg",
};

const COMBOS = {
  ...SHIRT_PANT_COMBOS,
  ...POLO_PANT_COMBOS,
  ...SWEATSHIRT_PANT_COMBOS,
};
const SINGLES = {
  ...SHIRT_SINGLE_RESULTS,
  ...POLO_SINGLE_RESULTS,
  ...SWEATSHIRT_SINGLE_RESULTS,
  ...PANTS_SINGLE_RESULTS,
};

// Returns the pre-generated photo of topId + bottomId worn together, or
// null if that exact pairing hasn't been generated.
export function getWesternComboResult(topId, bottomId) {
  return COMBOS[topId]?.[bottomId] || null;
}

// Returns the pre-generated photo of just the top on its own, or null.
export function getWesternSingleResult(topId) {
  return SINGLES[topId] || null;
}

// Best result available for a given top+bottom pairing: returns the exact
// combo if both are provided and that pairing exists; if only a top is
// provided (no bottom), returns the top's solo result. Returns null if
// nothing fits — callers should fall back to the live AI pipeline in that
// case, rather than silently swapping in an unrelated photo.
export function getWesternTryOnResult(topId, bottomId) {
  if (topId && bottomId) {
    return getWesternComboResult(topId, bottomId);
  }
  if (topId) {
    return getWesternSingleResult(topId);
  }
  if (bottomId) {
    return getWesternSingleResult(bottomId);
  }
  return null;
}

// Every garment id that has AT LEAST ONE real try-on photo somewhere —
// as a top with a single result, a top in a combo, or a pants id that
// shows up as a combo's bottom half. Used to gate the gallery so only
// garments that actually have something to show are selectable; anything
// else displays as "Coming Soon" instead of silently failing against the
// (often offline) live backend.
const COVERED_GARMENT_IDS = new Set([
  ...Object.keys(SINGLES),
  ...Object.keys(COMBOS),
  ...Object.values(COMBOS).flatMap((pantsMap) => Object.keys(pantsMap)),
]);

export function hasWesternResult(garmentId) {
  return COVERED_GARMENT_IDS.has(garmentId);
}
